function App() {
  return (
    <div className='App'>
        <Header/>
    <nav style={{ marginBottom: '2rem' }}>
      <link to="/" style={{ margin: '0 1rem' }}>Home</link>
      {/* <link to="/visualizations" style={{ margin: '0 1rem' }}>Visualizations</link> */}
    </nav>

     <Router>
          <Routes>
            <Route path="/" element={<AnalysisTable />}  />
            {/* <Route path='/visualizations'  /> */}
          </Routes>
      </Router>   
      {/* <div className='card-body'>
        <AnalysisTable/> 
      </div> */}
    </div>
  );
}

export default App;
